<template>
    <div class="c1-view">

      <!-- <el-switch v-model="value1" active-text="按月付费" inactive-text="按年付费">
          </el-switch> -->
      <div class="block">
        <span class="demonstration">巡查日期： </span>
        <el-date-picker v-model="checkdate" align="right" type="date" placeholder="选择日期" :picker-options="pickerOptions">
        </el-date-picker>
      </div>

      <br>
      <!-- 这里可以将文本输入框的值绑定为classname -->
      <el-checkbox-group v-model="checkboxClassGroup1" class="checkbox-group">
        <el-checkbox-button v-for="classname in classes" :label="classname" :key="classname" class="checkbox-button">{{ classname
          }}
          <el-autocomplete class="inline-input" v-model="states[classname]" :fetch-suggestions="querySearch"
            placeholder= "要表扬的教师" @input ="handleinput" @focus="handleFocus(classname)" @select="handleSelect">
            <!-- 添加一个清楚按钮插槽 -->
            <template v-slot:append>
              <el-button icon="el-icon-circle-close" @click="clearInput(classname)" slot="append"
                v-if="states[classname]" class="custom-clear-btn"></el-button>
            </template>
          </el-autocomplete>
        </el-checkbox-button>
      </el-checkbox-group>
  
      <br>
      <br>
      <div class="container">
        <div class="left-column">
          <!-- 放置按钮 -->
          <el-button type="danger" @click="uploaddata">暂存{{ grade1 }}数据</el-button>
          <br>
          <br>
          <el-button type="warning" @click="querydata">查询选定日期数据</el-button>
          <br>
          <br>
          <el-button type="success" @click="loadandquery">上传全部年级数据并生成反馈</el-button>
        </div>
        <div class="right-column">
          <!-- 放置文本 -->
          <p v-html="feedbacksentence" ></p>



          <!-- 图片缩略图展示区 -->
        <div class="image-container" v-for="(image, index) in images" :key="index">
          <img :src="image" class="thumbnail">
          <div class="overlay" @mouseover="hover = true" @mouseleave="hover = false">
            <i class="icon el-icon-zoom-in" @click="handlePreview(image)"></i>
            <i class="icon el-icon-download" @click="handleDownload(image)"></i>
            <i class="icon el-icon-delete" @click="handleRemove(index)"></i>
          </div>
        </div>

        <div v-if="isPreviewModalVisible" class="modal" @click="isPreviewModalVisible = false">
          <div class="modal-content" @click.stop>
            <span class="close" @click="isPreviewModalVisible = false">&times;</span>
            <img :src="previewImageUrl" class="preview-image">
          </div>
        </div>
        </div>
      </div>
  
  
  
    </div>
  
  
  </template>
  <style scoped>
